#===============================================================================
# FILE    : sta_main.tcl
# PURPOSE : PrimeTime STA flow master script.
#           Sources the numbered step scripts (1_setup.tcl .. 10_rpt.tcl) in
#           the order they are listed, so each step is read in numeric order as
#           requested. Invoked by run/run_sta.csh through pt_shell.
#===============================================================================

#---- global defaults (overridden by the -x assignments from run_sta.csh) ------
if {![info exists ROOT_DIR]}    { set ROOT_DIR    [file normalize [file dirname [pwd]]] }
if {![info exists RUN_DIR]}     { set RUN_DIR     [file join $ROOT_DIR run] }
if {![info exists SCR_DIR]}     { set SCR_DIR     [file join $ROOT_DIR scr] }
if {![info exists LOG_DIR]}     { set LOG_DIR     [file join $ROOT_DIR log] }
if {![info exists RPT_DIR]}     { set RPT_DIR     [file join $ROOT_DIR rpt] }
if {![info exists SDC_DIR]}     { set SDC_DIR     [file join $ROOT_DIR sdc] }
if {![info exists SES_DIR]}     { set SES_DIR     [file join $ROOT_DIR session] }
if {![info exists DESIGN_NAME]} { set DESIGN_NAME "design" }
if {![info exists PT_CORNER]}   { set PT_CORNER   "tt0p8v25c" }
if {![info exists PT_MODE]}     { set PT_MODE     "func" }

file mkdir $LOG_DIR $RPT_DIR $SDC_DIR $SES_DIR

puts "=================================================================="
puts " PrimeTime STA Flow : sta_main.tcl"
puts " design             : $DESIGN_NAME"
puts " corner             : $PT_CORNER"
puts " mode               : $PT_MODE"
puts "=================================================================="

# Continue on error so a single failing report does not abort the whole flow;
# the log/reports still get written and can be inspected.
set sh_continue_on_error true
set sh_command_log_file [file join $LOG_DIR "sta_commands_${DESIGN_NAME}_${PT_CORNER}_${PT_MODE}.log"]

# Numbered step scripts, sourced strictly in read (numeric) order.
set STEP_SCRIPTS [list \
    1_setup.tcl          \
    2_read_constraint.tcl \
    3_read_library.tcl    \
    4_read_netlist.tcl    \
    5_link_design.tcl     \
    6_timing_config.tcl   \
    7_update_timing.tcl   \
    8_report_timing.tcl   \
    9_write_output.tcl    \
    10_rpt.tcl            \
]

foreach step $STEP_SCRIPTS {
    set step_file [file join $SCR_DIR $step]
    puts "RM-Info: ================= source $step ================="
    if {[file exists $step_file]} {
        source $step_file
    } else {
        puts "RM-Error: missing step script $step_file"
    }
}

puts "RM-Info: sta_main.tcl finished for design $DESIGN_NAME (corner=$PT_CORNER, mode=$PT_MODE)"

#===============================================================================
# FILE    : 2_read_constraint.tcl
# PURPOSE : Read timing constraints (SDC) for the selected corner/mode.
#           The SDC is read in before link_design so all clocks / input-output
#           delays / timing exceptions are applied to the linked design.
#===============================================================================
puts "RM-Info: [info script] : reading timing constraints"

if {![info exists DATA_DIR]} { set DATA_DIR [file join $ROOT_DIR data] }

# Determine the SDC file(s). The mode allows a dedicated test/hold SDC directory
# to be picked automatically; otherwise the flat sdc/ directory is used.
if {![info exists CONSTRAINT_FILES]} {
    set CONSTRAINT_FILES ""
    set sdc_search_dirs [list \
        [file join $DATA_DIR "sdc" $PT_MODE] \
        [file join $DATA_DIR "sdc"] ]

    foreach sdir $sdc_search_dirs {
        if {$CONSTRAINT_FILES eq ""} {
            set CONSTRAINT_FILES [glob -nocomplain [file join $sdir "*.sdc"]]
        }
    }
}
set CONSTRAINT_FILES [string trim $CONSTRAINT_FILES]
puts "RM-Info: CONSTRAINT_FILES = $CONSTRAINT_FILES"

if {$CONSTRAINT_FILES eq ""} {
    puts "RM-Warning: no SDC found; the design will be unconstrained"
} else {
    foreach sdc $CONSTRAINT_FILES {
        if {[file exists $sdc]} {
            puts "RM-Info: read_sdc $sdc"
            read_sdc $sdc
        } else {
            puts "RM-Warning: SDC not found: $sdc"
        }
    }
}

# Mode specific extra-constraint handling (kept as extension points).
switch -exact -- $PT_MODE {
    "test" {
        # Typical scan mode: relax/ignore scan-enable & shift timing here.
        puts "RM-Info: PT_MODE=test  -> apply scan-mode timing exceptions"
    }
    "hold" {
        # Hold closure: hold margins are reported in step 8/10.
        puts "RM-Info: PT_MODE=hold  -> hold-corner analysis"
    }
    default {
        puts "RM-Info: PT_MODE=func  -> functional setup/hold analysis"
    }
}

puts "RM-Info: [info script] completed"

#===============================================================================
# FILE    : 3_read_library.tcl
# PURPOSE : Submodule library input files reading.
#           Reads the corner-specific submodule Liberty databases (.db) and adds
#           them to the link path so that submodule cells (memory / IO / hard
#           macro) resolve correctly during link_design.
#===============================================================================
puts "RM-Info: [info script] : reading submodule libraries"

if {![info exists DATA_DIR]} { set DATA_DIR [file join $ROOT_DIR data] }
if {![info exists LIB_BASE]} { set LIB_BASE   [file join $DATA_DIR "lib" $PT_CORNER] }

# Submodule Liberty inputs: collected from the corner lib sub-directory and from
# an optional dedicated sub-module library directory.
if {![info exists SUBMODULE_LIB_FILES]} {
    set SUBMODULE_LIB_FILES ""
    set sub_dirs [list \
        [file join $LIB_BASE "sub"] \
        [file join $DATA_DIR "sub_lib" $PT_CORNER] ]
    foreach sub_dir $sub_dirs {
        foreach L [glob -nocomplain [file join $sub_dir "*.db"]] {
            lappend SUBMODULE_LIB_FILES $L
        }
        foreach L [glob -nocomplain [file join $sub_dir "*.lib"]] {
            lappend SUBMODULE_LIB_FILES $L
        }
    }
}
set SUBMODULE_LIB_FILES [string trim $SUBMODULE_LIB_FILES]
puts "RM-Info: SUBMODULE_LIB_FILES = $SUBMODULE_LIB_FILES"

foreach L $SUBMODULE_LIB_FILES {
    if {[string match "*.db" $L]} {
        puts "RM-Info: read_db $L"
        read_db $L
    } else {
        puts "RM-Warning: '$L' is a Liberty source (.lib); compile it into a .db"
        puts "            with Library Compiler (lc_shell) before PT reads it."
    }
}

# Extend the link path so submodule cells resolve at link_design time.
set link_path [concat $link_path $SUBMODULE_LIB_FILES]

puts "RM-Info: [info script] completed"

#===============================================================================
# FILE    : 4_read_netlist.tcl
# PURPOSE : Read the gate-level Verilog netlist(s): top design plus submodules.
#===============================================================================
puts "RM-Info: [info script] : reading gate-level netlist"

if {![info exists DATA_DIR]} { set DATA_DIR [file join $ROOT_DIR data] }

if {![info exists NETLIST_FILES]} {
    set NETLIST_FILES [glob -nocomplain [file join $DATA_DIR "netlist" "*.v"]]
    if {[llength $NETLIST_FILES] == 0} {
        set NETLIST_FILES [glob -nocomplain [file join $DATA_DIR "netlist" "*.vg"]]
    }
}
set NETLIST_FILES [string trim $NETLIST_FILES]
puts "RM-Info: NETLIST_FILES = $NETLIST_FILES"

if {$NETLIST_FILES eq ""} {
    puts "RM-Error: no gate-level netlist found under $DATA_DIR/netlist"
} else {
    foreach vf $NETLIST_FILES {
        puts "RM-Info: read_verilog $vf"
        read_verilog $vf
    }
}

puts "RM-Info: [info script] completed"

